Stream<Trade> two = Stream.concat(exchangeTrades.stream(), internalTrades.stream());

// ═══ THREE+ streams: flatMap is cleaner ═══
Stream<Trade> three = Stream.of(
    exchangeTrades.stream(),
    internalTrades.stream(),
    manualTrades.stream()
).flatMap(Function.identity());

// ═══ MANY streams: nested concat is ugly ═══
// (Avoid) Deep nesting:
Stream<Trade> ugly = Stream.concat(
    Stream.concat(
        Stream.concat(s1, s2), s3), s4);

// (Recommended) Flat with flatMap:
Stream<Trade> clean = Stream.of(s1, s2, s3, s4).flatMap(s -> s);

// ═══ CLOSING: concat closes BOTH inputs on close ═══
// If s1 or s2 are from Files.lines (AutoCloseable), concat propagates close.
