@Test void concatForTwoStreams() {
    List<String> result = Stream.concat(Stream.of("A", "B"), Stream.of("C", "D")).toList();
    assertThat(result).containsExactly("A", "B", "C", "D");
}

@Test void flatMapForManyStreams() {
    List<String> result = Stream.of(Stream.of("A"), Stream.of("B"), Stream.of("C"))
        .flatMap(Function.identity()).toList();
    assertThat(result).containsExactly("A", "B", "C");
}

@Test void bothProduceSameResult() {
    var s1 = List.of("A", "B"); var s2 = List.of("C"); var s3 = List.of("D", "E");
    var concat = Stream.concat(Stream.concat(s1.stream(), s2.stream()), s3.stream()).toList();
    var flat = Stream.of(s1.stream(), s2.stream(), s3.stream()).flatMap(s -> s).toList();
    assertThat(concat).isEqualTo(flat);
}
