package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.function.Function;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.assertThat;

class ConcatTest {

    @Test
    void concatTwoVsFlatMapForMany() {
        var domestic = Stream.of("DOM1", "DOM2");
        var intl     = Stream.of("INT1");

        List<String> two = Stream.concat(domestic, intl).toList();
        assertThat(two).containsExactly("DOM1", "DOM2", "INT1");

        List<String> many = Stream.of(Stream.of("A"), Stream.of("B"), Stream.of("C"))
            .flatMap(Function.identity())
            .toList();
        assertThat(many).containsExactly("A", "B", "C");
    }
}
